#include "one_click.hpp"
#include <iostream>
using namespace usb;namespace e=enhanced;
static int passed=0;
static void check(bool ok,const char* message){if(!ok)throw Error{fromUtf8(message)};++passed;std::cout<<"PASS "<<message<<std::endl;}
static void rejects(const std::function<void()>& fn,const char* message){bool rejected=false;try{fn();}catch(const Error&){rejected=true;}check(rejected,message);}
int wmain(int argc,wchar_t** argv){try{
    if(argc!=2)return 2;
    S base=full(argv[1]);mkdir(base);auto quiet=[](const S&){};
    auto makeDisk=[&](const S& label){S root=join(base,label);mkdir(root);return e::DiskTarget{root,label,volume(root)};};
    auto addDoc=[&](const e::DiskTarget& disk){S container=join(disk.root,L"\uffff");mkdir(container);SetFileAttributesW(xp(container).c_str(),FILE_ATTRIBUTE_HIDDEN|FILE_ATTRIBUTE_SYSTEM);
        textFile(join(container,L"document.txt"),L"safe document");return container;};
    auto first=makeDisk(L"usb-a"),second=makeDisk(L"usb-b"),untouched=makeDisk(L"not-selected");
    S ca=addDoc(first),cb=addDoc(second),cu=addDoc(untouched);
    textFile(join(ca,L"payload.bin"),L"inert test indicator");textFile(join(cb,L"payload.bin"),L"inert test indicator");
    textFile(join(cu,L"payload.bin"),L"inert test indicator");
    S payloadDigest=hash(join(ca,L"payload.bin")),docDigest=hash(join(ca,L"document.txt"));
    e::HashRule exact{payloadDigest,L"fixture",L"fixture",L"fixture",size(join(ca,L"payload.bin"))};
    std::vector<e::HashRule> catalog{exact};
    textFile(join(first.root,L"document.txt"),L"keep original");
    S hiddenFolder=join(first.root,L"photos");mkdir(hiddenFolder);textFile(join(hiddenFolder,L"photo.txt"),L"picture");
    SetFileAttributesW(xp(hiddenFolder).c_str(),FILE_ATTRIBUTE_HIDDEN|FILE_ATTRIBUTE_SYSTEM);
    S hiddenFile=join(second.root,L"hidden.txt");textFile(hiddenFile,L"hidden document");SetFileAttributesW(xp(hiddenFile).c_str(),FILE_ATTRIBUTE_HIDDEN|FILE_ATTRIBUTE_SYSTEM);
    e::ScanSession usb;e::initializeUsbOnly(usb,first,true);
    check(usb.groups.size()==1 && usb.groups[0].removable && usb.groups[0].roots.size()==1 && same(usb.groups[0].roots[0],first.root),"USB-only initializes exactly the selected device without any host group");
    check(usb.scanner.tempRoots.empty() && usb.scanner.riskRoots.empty(),"USB-only has no computer directory scopes");
    rejects([&]{e::initializeUsbOnly(usb,first);},"production USB initialization rejects ordinary directories");
    auto changed=first;changed.serial^=1;
    rejects([&]{e::initializeUsbOnly(usb,changed,true);},"replaced volume is rejected before scanning");
    e::ScanSession full;e::ScanGroup immediate{L"processes",false,true,{}, {}, {}};
    immediate.direct.push_back({L"C:\\host.exe",0,0,{}});immediate.direct.push_back({L"F:\\usb.exe",0,0,{}});full.groups.push_back(immediate);
    e::addFixedDisks(full,{L"C:\\",L"D:\\"});
    check(full.groups.back().roots.size()==2 && full.groups.back().directories.size()==2,"full scan includes every fixed disk from its inventory");
    check(full.groups.front().direct.size()==1 && full.groups.front().direct.front().path==L"C:\\host.exe","USB process references belong only to their volume-bound scan and cannot be quarantined twice");
    e::OneClickResult result;std::vector<size_t> counts;
    e::runAutomatic(result,e::RunMode::UsbOnly,{first,second},quiet,[&](const S&,size_t n){counts.push_back(n);},{},2,true,join(base,L"journals"),catalog);
    check(result.usbs.size()==2 && !result.host.scan.initialized,"one-click runs both selected devices without initializing the computer");
    check(result.usbs[0].scan.pages>1 && result.usbs[1].scan.complete,"one-click continues bounded scan pages automatically");
    check(result.isolated==2 && result.unresolved==0 && result.issues.empty(),"both inert indicators are automatically isolated");
    check(result.restored==4 && result.skipped==0,"both containers and ordinary hidden data are restored in the same operation");
    check(hash(join(first.root,L"document（恢复1）.txt"))==docDigest && hash(join(first.root,L"document.txt"))!=docDigest,"automatic recovery preserves both colliding documents");
    check(hash(join(second.root,L"document.txt"))==docDigest,"second device document returns to its root unchanged");
    check(exists(join(hiddenFolder,L"photo.txt")) && !exists(join(first.root,L"photo.txt")),"ordinary hidden folders keep their directory structure");
    check(!(attr(hiddenFolder)&(FILE_ATTRIBUTE_HIDDEN|FILE_ATTRIBUTE_SYSTEM)) && !(attr(hiddenFile)&(FILE_ATTRIBUTE_HIDDEN|FILE_ATTRIBUTE_SYSTEM)),"hidden folder and root document attributes become visible");
    check(!exists(ca) && !exists(cb),"only empty special containers are removed after recovery");
    check(exists(join(cu,L"payload.bin")) && exists(join(cu,L"document.txt")),"unselected device remains unchanged");
    bool monotonic=true;for(size_t i=1;i<counts.size();++i)if(counts[i]<counts[i-1])monotonic=false;
    check(monotonic && !counts.empty() && counts.back()==result.checked,"multi-device progress count never resets");
    auto report=e::automaticReport(result);
    check(report.content.find(e::usbOnlyReminder())!=S::npos && report.content.size()<180,"USB completion includes concise reinfection and full-scan reminder");
    check(!report.warning,"successful bounded cleanup produces success rather than a failure report");
    auto unknown=makeDisk(L"unknown");S unknownContainer=addDoc(unknown);textFile(join(unknownContainer,L"DrvMgr.exe"),L"unknown executable");
    e::OneClickResult retained;e::runAutomatic(retained,e::RunMode::UsbOnly,{unknown},quiet,{}, {},2,true,join(base,L"unknown-journals"),catalog);
    check(exists(join(unknownContainer,L"DrvMgr.exe")) && retained.isolated==0,"unknown same-name executable is not automatically deleted");
    check(exists(join(unknownContainer,L"document.txt")) && retained.restored==0 && e::automaticReport(retained).warning,"unreviewed high risk blocks restoration and is reported");
    auto partial=makeDisk(L"partial");S partialContainer=addDoc(partial);textFile(join(partialContainer,L"normal.exe"),L"ordinary executable");
    e::OneClickResult partialResult;e::runAutomatic(partialResult,e::RunMode::UsbOnly,{partial},quiet,{}, {},2,true,join(base,L"partial-journals"),catalog);
    check(exists(join(partial.root,L"document.txt")) && exists(join(partial.root,L"normal.exe")) && !exists(partialContainer),"ordinary executable data returns to root with documents and emptied wrapper is removed");
    check(partialResult.skipped==0 && !e::automaticReport(partialResult).warning,"ordinary application files do not produce skipped-file warnings");
    auto cancelled=makeDisk(L"cancelled");S cancelledContainer=addDoc(cancelled);textFile(join(cancelledContainer,L"payload.bin"),L"inert test indicator");
    e::OneClickResult stopped;e::runAutomatic(stopped,e::RunMode::UsbOnly,{cancelled},quiet,{},[]{return true;},2,true,join(base,L"cancelled-journals"),catalog);
    check(stopped.stopped && !exists(join(base,L"cancelled-journals")) && exists(join(cancelledContainer,L"payload.bin")),"stop before scan never begins quarantine or restoration");
    check(e::automaticReport(stopped).headline==L"操作已停止" && e::automaticReport(stopped).content.find(L"未发现本工具")==S::npos,"cancellation cannot report a clean scan");
    auto bad=makeDisk(L"changed-before-clean");S badContainer=addDoc(bad);textFile(join(badContainer,L"payload.bin"),L"inert test indicator");
    e::OneClickResult failure;bool replaced=false;
    e::runAutomatic(failure,e::RunMode::UsbOnly,{bad},quiet,[&](const S& path,size_t){if(!replaced && path.find(L"清理 U 盘：")==0){
        replaced=true;SetFileAttributesW(xp(join(badContainer,L"payload.bin")).c_str(),FILE_ATTRIBUTE_NORMAL);
        Handle file(CreateFileW(xp(join(badContainer,L"payload.bin")).c_str(),GENERIC_WRITE,0,nullptr,TRUNCATE_EXISTING,0,nullptr));write(file.h,"changed",7);}}, {},2,true,join(base,L"failure-journals"),catalog);
    check(replaced && failure.isolated==0 && failure.restored==0 && exists(join(badContainer,L"document.txt")),"changed file fails revalidation and blocks automatic restoration");
    check(e::automaticReport(failure).warning && e::automaticReport(failure).content.find(L"未发现本工具")==S::npos,"cleanup failure cannot claim no known virus was found");
    e::Workflow host;host.scan.initialized=true;host.scan.complete=true;host.registryChecked=true;host.inventoryComplete=true;
    e::requireHostReady(host);check(true,"completed host scan permits USB restoration gate");
    host.treatment.add(e::ActionKind::Startup,e::ActionStatus::Failed,L"inert",L"fixture",true);
    rejects([&]{e::requireHostReady(host);},"failed host persistence prevents USB restoration");
    host.treatment={};host.scan.criticalErrors.push_back(L"fixture unreadable");
    host.registryChecked=false;host.inventoryComplete=false;
    e::requireHostReady(host);check(true,"unrelated host access failures no longer block USB restoration");
    host.scan.findings.push_back({L"C:\\known-virus.bin",L"",L"fixture",true,false});
    rejects([&]{e::requireHostReady(host);},"known remaining host virus still prevents USB restoration");
    host.scan.findings.clear();host.scan.complete=false;
    rejects([&]{e::requireHostReady(host);},"unfinished host scan still prevents automatic restoration");
    int hostCalls=0;e::HostActions hooks{[&](const Finding&,Journal&,Log){++hostCalls;},[&](const Finding&,Journal&,Log){++hostCalls;}};
    auto boundary=makeDisk(L"host-boundary");S boundaryContainer=addDoc(boundary);S boundaryPayload=join(boundaryContainer,L"payload.bin");textFile(boundaryPayload,L"inert test indicator");
    e::Workflow boundaryWork;e::Scanner scanner(catalog);scanner.inspect(boundaryPayload,boundaryWork.scan.findings,quiet);
    {Journal j(join(base,L"boundary-journals"));e::treatAutomatic(boundaryWork,false,j,quiet,catalog,&hooks);}
    check(hostCalls==0 && !exists(boundaryPayload),"USB treatment never invokes host termination or startup hooks");
    e::HashRule knownOnly=exact;knownOnly.expectedSize=0;
    auto hashDisk=makeDisk(L"known-hash");S hashContainer=addDoc(hashDisk);textFile(join(hashContainer,L"payload.bin"),L"inert test indicator");
    e::OneClickResult hashResult;e::runAutomatic(hashResult,e::RunMode::UsbOnly,{hashDisk},quiet,{}, {},2,true,join(base,L"hash-journals"),{knownOnly});
    check(hashResult.isolated==1 && hashResult.restored==1 && !exists(join(hashContainer,L"payload.bin")),"known hash without registered size is revalidated and quarantined in one click");
    auto fullDisk=makeDisk(L"full-recovery");S fullContainer=addDoc(fullDisk);
    S fullPayload=join(fullContainer,L"payload.bin");textFile(fullPayload,L"inert test indicator");
    textFile(join(fullDisk.root,L"document.txt"),L"keep root document");
    SetFileAttributesW(xp(fullContainer).c_str(),FILE_ATTRIBUTE_HIDDEN|FILE_ATTRIBUTE_SYSTEM|FILE_ATTRIBUTE_READONLY);
    e::OneClickResult fullResult;fullResult.mode=e::RunMode::Full;fullResult.host.scan.initialized=true;fullResult.host.scan.complete=true;
    fullResult.host.scan.criticalErrors={L"cannot read unrelated computer folder"};fullResult.host.inventoryComplete=false;fullResult.host.registryChecked=false;
    fullResult.usbs.emplace_back();auto& fullUsb=fullResult.usbs.back();e::initializeUsbOnly(fullUsb.scan,fullDisk,true);
    fullUsb.scan.scanner=e::Scanner(catalog);fullUsb.scan.scanner.usbRoot=fullDisk.root;
    while(!fullUsb.scan.complete)e::scanPage(fullUsb.scan,quiet,{}, {},2);
    fullUsb.scan.criticalErrors={L"cannot read unrelated USB entry"};
    fullResult.issues={L"access denied details must stay in logs"};
    {Journal journal(join(base,L"full-journals"));e::treatAutomatic(fullUsb,false,journal,quiet,catalog);e::recheckAutomatic(fullUsb,false,quiet,1,0);
        e::restoreAutomaticDisks(fullResult,journal,quiet,{}, {},true);}
    e::summarizeAutomatic(fullResult);
    check(fullResult.isolated==1 && fullResult.restoredPaths.size()==1 && fullResult.recoveryFailures==0,"full-mode cleanup reaches actual restoration despite unrelated access failures");
    check(hash(join(fullDisk.root,L"document（恢复1）.txt"))==docDigest && exists(join(fullDisk.root,L"document.txt")),"full-mode recovery moves data to root without overwriting original");
    check(!exists(fullContainer) && fullResult.removedContainers.size()==1,"full-mode recovery deletes verified empty read-only hidden container");
    auto concise=e::automaticReport(fullResult);
    check(concise.details.find(fullPayload)!=S::npos && concise.details.find(L"document（恢复1）.txt")!=S::npos,"result details name successfully cleaned payload and restored destination");
    check(concise.details.find(L"access denied")==S::npos && concise.details.find(L"cannot read")==S::npos && concise.details.find(L"64 MiB")==S::npos,"result details omit inaccessible paths and scan limitations");
    check(!concise.warning && concise.content.find(L"恢复到根目录")!=S::npos,"successful full restoration is summarized without unrelated access warnings");
    e::OneClickResult noRestore;noRestore.mode=e::RunMode::Full;noRestore.issues={L"diagnostic"};
    check(e::automaticReport(noRestore).content.find(L"没有文件移回")!=S::npos,"zero restoration cannot be described as files restored to root");
    e::OneClickResult replacedTarget;
    e::runAutomatic(replacedTarget,e::RunMode::UsbOnly,{changed},quiet,{}, {},2,true,join(base,L"replaced-journals"),catalog);
    check(replacedTarget.recoveryFailures==1 && e::automaticReport(replacedTarget).warning,"device replacement remains a visible failure while routine access diagnostics stay out of results");
    std::cout<<"TOTAL PASS "<<passed<<std::endl;return 0;
}catch(const Error& error){std::cerr<<utf8(error.text)<<std::endl;return 1;}}
